I'll move all Design notebooks to Archive.

```json
{
  "intent": "bulk_move",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "SELECT",
      "purpose": "Find Archive workspace",
      "sql": "SELECT id FROM workspaces WHERE name = 'Archive' LIMIT 1"
    },
    {
      "op": "SELECT",
      "purpose": "Find Design notebooks",
      "sql": "SELECT o.id, o.name FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN groups g ON w.group_id = g.id WHERE g.name = 'Design' AND o.board_mode = 'notebook'"
    },
    {
      "op": "UPDATE",
      "table": "objects",
      "set": {"workspace_id": "{{result[0].id}}", "updated_at": "{{now}}"},
      "where": {"id": {"$in": "{{result[1].map(r => r.id)}}"}}
    }
  ],
  "confirmation": "Move {{result[1].length}} notebooks from Design to Archive?"
}
```

```sql
SELECT DISTINCT o.id, o.name FROM objects o JOIN notebook_cells nc ON nc.board_id = o.id WHERE nc.cell_type = 'mermaid' AND o.archived = 0;
```

```sql
SELECT o.id, o.name, w.name as workspace FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN groups g ON w.group_id = g.id WHERE g.name = 'Management' AND o.archived = 0;
```

I'll duplicate this board in the same workspace.

```json
{
  "intent": "duplicate",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "SELECT",
      "purpose": "Get current board",
      "sql": "SELECT * FROM objects WHERE id = :current_board_id"
    },
    {
      "op": "INSERT",
      "table": "objects",
      "values": {
        "id": "{{generate_uuid}}",
        "workspace_id": "{{result[0].workspace_id}}",
        "type": "{{result[0].type}}",
        "name": "{{result[0].name}} (Copy)",
        "board_mode": "{{result[0].board_mode}}",
        "created_at": "{{now}}"
      },
      "save_as": "new_board"
    },
    {
      "op": "SELECT",
      "purpose": "Get cells",
      "sql": "SELECT * FROM notebook_cells WHERE board_id = :current_board_id ORDER BY cell_order"
    },
    {
      "op": "INSERT_EACH",
      "table": "notebook_cells",
      "for_each": "{{result[2]}}",
      "values": {
        "id": "{{generate_uuid}}",
        "board_id": "{{new_board.id}}",
        "cell_type": "{{item.cell_type}}",
        "content": "{{item.content}}",
        "cell_order": "{{item.cell_order}}",
        "created_at": "{{now}}"
      }
    }
  ],
  "confirmation": "Duplicate this board?"
}
```

I'll rename the group.

```json
{
  "intent": "rename",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "UPDATE",
      "table": "groups",
      "set": {"name": "Development"},
      "where": {"name": "Engineering"}
    }
  ],
  "confirmation": "Rename 'Engineering' group to 'Development'?"
}
```

```sql
SELECT COUNT(*) as board_count FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN groups g ON w.group_id = g.id WHERE g.name = 'Marketing' AND o.type = 'whiteboard' AND o.archived = 0;
```

```sql
SELECT DISTINCT o.id, o.name FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN groups g ON w.group_id = g.id JOIN board_metadata bm ON bm.board_id = o.id JOIN notebook_cells nc ON nc.board_id = o.id WHERE g.name = 'Design' AND o.board_mode = 'notebook' AND bm.starred = 1 AND nc.cell_type = 'mermaid';
```

```sql
SELECT DISTINCT o.id, o.name FROM objects o JOIN workspaces w ON o.workspace_id = w.id WHERE w.id IN (SELECT o2.workspace_id FROM objects o2 JOIN board_metadata bm ON bm.board_id = o2.id WHERE bm.template = 1);
```

```sql
SELECT g.name FROM groups g WHERE g.id NOT IN (SELECT DISTINCT w.group_id FROM workspaces w JOIN objects o ON o.workspace_id = w.id WHERE o.type = 'whiteboard');
```

```sql
SELECT DISTINCT o.id, o.name FROM objects o JOIN board_metadata bm ON bm.board_id = o.id JOIN notebook_cells nc ON nc.board_id = o.id WHERE bm.template = 1 AND nc.cell_type = 'mermaid';
```

```sql
SELECT o.id, o.name, w.name as workspace FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN board_metadata bm ON bm.board_id = o.id WHERE bm.starred = 1 AND o.archived = 0;
```

```sql
SELECT id, name, icon, color FROM groups ORDER BY name;
```

I'll archive boards not updated in 90 days.

```json
{
  "intent": "bulk_archive",
  "requires_confirmation": true,
  "actions": [
    {
      "op": "SELECT",
      "purpose": "Find old boards",
      "sql": "SELECT id, name FROM objects WHERE type = 'whiteboard' AND archived = 0 AND updated_at < strftime('%s', 'now', '-90 days')"
    },
    {
      "op": "UPDATE",
      "table": "objects",
      "set": {"archived": 1, "updated_at": "{{now}}"},
      "where": {"id": {"$in": "{{result[0].map(r => r.id)}}"}}
    }
  ],
  "confirmation": "Archive {{result[0].length}} boards not updated in 90 days?",
  "preview": "{{result[0].map(r => r.name).join(', ')}}"
}
```

I'll move all files to the Archive workspace.

```json
{
  "intent": "bulk_move",
  "requires_confirmation": true,
  "actions": [
    {
